}
```
Reading an undeclared identifier normally throws ReferenceError; typeof is the one operator that does not, answering "undefined" instead. That is what makes runtime feature detection possible without a try/catch.

```js
"use strict";
const mode = "dark";
const bg = mode === "dark" ? "#111" : "#f5f5f5";     // (1)
const o = { x: 1, y: 2 };
delete o.x;                     // (2) true
"x" in o;                       // false
delete o.nope;                  // (3) true — nothing removed, still true
const frozen = Object.freeze({ keep: true });
delete frozen.keep;             // (4) TypeError!
```

concepts.statement:
A **block** is a set of braces containing zero or more statements, treated grammatically as a single statement:
```js
{
  let temp = compute();
  use(temp);
}                       // no semicolon after }
```
Blocks need no trailing semicolon. They are how if, for and while accept multiple-statement bodies — and with `let/const` they are **scopes**: bindings declared inside stay inside. `var` ignores block braces entirely (it is function-scoped), one of the reasons Chapter 3 retired it.

steps.text:
```js
"use strict";                         // (1)
let total = 0;                         // (2)
function bump(n) { return total += n; } // (3)
bump(3);                               // (4)
total++;                                // (5)
if (total > 3) {                        // (6)
  total = 0;                            // (7)
}                                       // (8)
```

concepts.statement:
There is no elseif keyword: the ladder is just repeated `else if`, where each else contains another if statement:
```js
if (n === 1) {
  // ...
} else if (n === 2) {
  // ...
} else {
  // all other cases
}
```
The tests evaluate top to bottom; the first truthy one wins and the rest are skipped. The ladder is the natural shape for range checks and ordered conditions — and the direct competitor of switch(true).

When if statements nest without braces, an else belongs to the **nearest if that can accept it** — not necessarily the one your indentation suggests:
```js
if (a === 1)
  if (b === 1)
    log("both");
  else
    log("a is 1, b is not");   // else pairs with the INNER if
```
The braces rule makes the pairing explicit and makes refactoring safe — adding a statement to the outer body cannot silently capture the else.

The switch statement evaluates one expression, then compares the result against each `case` label in order:
```js
switch (expression) {
  case value1:  statements1  // executed if expression === value1
  // ...
  default:     statements   // when no case matches
}
```
Three mechanics that matter: (1) matching uses **strict equality** — `switch (1)` does not match `case "1"`; (2) the **default** clause runs when nothing matches and may appear anywhere (top by convention when it is not the catch-all); (3) **case labels are expressions** — evaluated, in order, when the switch is reached, so a case can be any runtime value including function calls.

Inside a switch, execution does **not** stop at the end of a case — it keeps executing statements into the following cases until it hits a `break` (or `return`, `throw`, or the closing brace). Omitting break is therefore a **fallthrough**, and since it is usually a bug, intentional fallthrough should be rare and **explicitly commented**. The legitimate use is **grouping** cases that share a body:
```js
switch (month) {
  case 12: case 1: case 2:   // three labels, one body: deliberate
    return "winter";
  case 3: case 4: case 5:
    return "spring";
  // ... 6-9, 10-11 similarly
  default:
    return "unknown";
}
```
A `return` inside a case makes break unnecessary — the function is leaving anyway.

When the decision does not share one comparand — ranges, type mixes, predicates — switch on the constant `true`, and let the case expressions be the conditions:
```js
switch (true) {
  case score >= 90: return "A";
  case score >= 80: return "B";
  case score >= 70: return "C";
  default:          return "F";
}
```
Each case is tested as `true === (score >= 90)` and so on, top to bottom — an else-if ladder wearing switch syntax. It is a matter of taste; readability wins whichever way reads better.

steps.text:
```js
function check(a, b) {
  if (a === 1)
    if (b === 1)
      log("both");
  else
    log("a is not 1");     // indented to LOOK outer
  return "done";
}
check(1, 2);
```

```js
function shipping(kg) {
  let cost;
  switch (true) {
    case kg <= 1:  cost = 5;               // letter
    case kg <= 5:  cost = 8;  // missing break — BUG
    case kg <= 20: cost = 12; break;
    default:       cost = 30;
  }
  return cost;
}
shipping(2);   // (1)
shipping(5);   // (2)
```

```js
switch (true) {
  case kg <= 1:  cost = 5;  break;   // break added
  case kg <= 5:  cost = 8;  break;   // break added
  case kg <= 20: cost = 12; break;
  default:       cost = 30;
}
```
Now shipping(2) is 8, shipping(5) is 8, and every tier behaves — the switch(true) ladder with disciplined breaks is an else-if chain in disguise.

```js
function route(cmd) {
  switch (cmd) {
    case 1:    return "number route";
    case "1":  return "string route";
    default:   return "no route";
  }
}
route(1);      // (1)
route("1");    // (2)
route("one");  // (3)
```

concepts.statement:
`do statement while (expression);` puts the body first and the test after — so the body runs **at least once**, and only then does the condition decide whether to repeat. Note the required **semicolon after the closing parenthesis** — the one place ASI will not save you. do/while suits loops that must prime or consume something before the question makes sense:
```js
let input;
do {
  input = nextToken();
  process(input);
} while (input !== "END");   // ; required here
```
continue inside a do/while jumps to the condition check — the bottom of the loop, not the top.

Inside an async function, the for/of body may await — each iteration then finishes its asynchronous work before the next begins, which makes the loop **sequential**:
```js
async function loadAll(urls) {
  for (const url of urls) {
    const response = await fetch(url);   // one at a time
    log(response.status);
  }
}
```
Sequential is often exactly right (respecting rate limits, depending on each result). For independent work, Chapter 13 shows the parallel alternative — collecting promises and awaiting them together — and for iterating asynchronous SEQUENCES (streams), the `for await...of` statement of Section 13.4.

The older **for/in** enumerates the enumerable string property NAMES of any object — own properties AND inherited ones:
```js
const o = { a: 1, b: 2 };
for (const p in o) log(p);        // "a", "b"

const parent = { inherited: true };
const child = Object.create(parent);
child.own = 1;
for (const p in child) log(p);    // "own", "inherited" — BOTH
```
Iteration order: integer-like keys ascend first, then string keys in definition order. For null or undefined, the loop body runs zero times. On arrays it yields the index keys **as strings** — see the next concept.

steps.text:
```js
function readTokens(tokens) {
  const out = [];
  let t, i = 0;
  do {
    t = tokens[i++];
    out.push(t.toUpperCase());
  } while (t !== "END");
  return out;
}
readTokens(["a", "b", "END"]);   // (1)
readTokens(["END"]);             // (2)
```

```js
let t = tokens[i++];             // prime BEFORE the loop
while (t !== "END") {
  out.push(t.toUpperCase());
  t = tokens[i++];               // and re-prime at the bottom
}
```
The same logic as a while duplicates the read twice — and the immediate-END case returns [] instead of ["END"], because the test now runs before the first push. The two forms differ on exactly the first iteration.

```js
let sum = 0;
for (let i = 1; i <= 5; i++) {
  sum += i;
}
// sum === ?
```

```js
for (;;) {                  // infinite: omitted test means true
  if (done()) break;        // escape hatch: break (Section 5.4)
}
```
Every clause is optional: an empty test is true forever; the initialize or increment can move out (or in) as needed. The semicolons, however, are load-bearing — a for header is exactly two semicolons, whatever sits around them.

```js
const arr = ["x", "y", "z"];
arr.tag = "letters";
for (const k in arr) log(k);     // (1)
for (const v of arr) log(v);      // (2)

const parent = { inherited: true };
const child = Object.create(parent);
child.own = 1;
for (const k in child) log(k);   // (3)
for (const k in child) {
  if (Object.hasOwn(child, k)) log(k);   // (4) filtered
}
for (const k of Object.keys(child)) log(k); // (5) keys are own-only
```

concepts.statement:
Any statement can carry a **label** — an identifier followed by a colon:
```js
mainloop: while (token !== null) {
  // ...
}
```
By convention labels are plain identifiers (not reserved), indented alone on their line for big loops. They exist for exactly one audience: break and continue, which may name a label to jump out of or to the next iteration of an **enclosing** labeled loop. A label never changes control flow by itself.

break exits the **nearest** enclosing loop or switch statement immediately. Its labeled form names a specific enclosing label and jumps past the end of THAT statement — the escape hatch for nested loops:
```js
outer: for (let r = 0; r < rows; r++) {
  for (let c = 0; c < cols; c++) {
    if (found(r, c)) break outer;   // leave BOTH loops
  }
}
```
An unlabeled break in the inner loop would merely advance to the next row — the label is what makes the double exit one statement.

continue skips the rest of the current iteration and starts the next one of the nearest enclosing LOOP (it is meaningless in a switch — that is not a loop). Its target depends on the loop: in a while, control goes to the **re-test**; in a for, to the **increment** (then the test); in a do/while, to the **bottom condition**. The labeled form, `continue label;`, skips to the next iteration of an OUTER labeled loop — useful for "abandon this inner pass and this outer item, next item":
```js
outer: for (const line of lines) {
  for (const word of line.split(" ")) {
    if (word === "SKIP") continue outer;  // next line, not next word
    emit(word);
  }
}
```

`return expression;` terminates the function and delivers the expression’s value; a bare `return;` delivers undefined. The hazard is **automatic semicolon insertion** (Section 2.5): a line break between return and its expression makes ASI supply a semicolon, so the function returns undefined and the orphaned expression runs (unreachably) on the next line:
```js
function bad() {
  return              // ASI inserts ; HERE
    { ok: true };     // never reached as a value
}
bad();                // undefined, not { ok: true }
```
Keep the value on the same line as return — or open a parenthesis on that line and let the expression continue below.

The **yield** keyword appears only inside generator functions (Chapter 12). `yield expression` hands the expression’s value out to the caller and **suspends** the generator right there — variable bindings, loop position, everything — until the caller asks for the next value:
```js
function* fib() {
  let [a, b] = [0, 1];
  for (;;) {
    yield a;          // pause here, deliver a
    [a, b] = [b, a + b];
  }
}
```
Where return leaves, yield pauses — the statement that makes infinite sequences representable.

`throw expression;` raises an exception: the expression’s value is thrown, and the enclosing statements unwind until a catch handles it — or the program terminates with the error on the console. **Any value can be thrown** (`throw 42;` is legal), but the universal practice is to throw an **Error object**, because it carries a message and a stack trace:
```js
function factorial(n) {
  if (n < 0) throw new RangeError("n must be non-negative");
  return n <= 1 ? 1 : n * factorial(n - 1);
}
```
The standard subclasses — TypeError, RangeError, SyntaxError and friends — are cataloged in Section 11.4.

The full exception-handling statement:
```js
try {
  // statements that might throw
} catch (e) {
  // runs ONLY if the try threw; e is the thrown value
} finally {
  // ALWAYS runs — after try, after catch, even through return/throw
}
```
The rules that matter: the **first** exception in try jumps directly to catch (skipping the rest of try); catch is optional-in-spirit (ES2019 even allows omitting the binding); and **finally runs no matter how the try or catch ended** — normal completion, return, break, continue, or an in-flight exception. If finally itself returns or throws, **it overrides** whatever was pending.

steps.text:
```js
const grid = [[1, 2, 3], [4, 5, 6], [7, 8, 9]];
function find(grid, target) {
  let found = null;
  outer: for (let r = 0; r < grid.length; r++) {
    for (let c = 0; c < grid[r].length; c++) {
      if (grid[r][c] === target) {
        found = [r, c];
        break outer;            // exit BOTH loops at once
      }
    }
  }
  return found;                 // reached whether found or not
}
find(grid, 5);                  // (1)
find(grid, 99);                 // (2)
```

```js
outer: for (const line of lines) {
  for (const word of line.split(" ")) {
    if (word === "SKIP") continue outer;
    emit(word);
  }
}
```
Same labeling, different jump: continue outer abandons the entire inner loop for THIS line and proceeds with the next line — "skip this record" as one statement instead of a flag and two breaks.

```js
function status(signedIn) {
  return                  // <-- ASI inserts a semicolon here
    { ok: signedIn };
}
status(true);              // (1)

function fixed(signedIn) {
  return {                // opening brace on the SAME line
    ok: signedIn
  };
}
fixed(true);               // (2)
```

```js
function risky(n) {
  if (n < 0) throw new RangeError("negative");
  return n * 2;
}

function demo(n) {
  try {
    const v = risky(n);
    return "got " + v;
  } catch (e) {
    if (e instanceof RangeError) return "handled: " + e.message;
    throw e;                     // rethrow the unfamiliar
  } finally {
    log("finally: always");     // runs on every path
  }
}

demo(5);    // (1)
demo(-1);   // (2)

function sneaky() {
  try { return "from try"; }
  finally { return "from finally"; }  // overrides!
}
sneaky();   // (3)
```

