  return { x, y }; // shorthand — Section 6.6
}
```
A trailing comma after the last property is legal. Every literal gets `Object.prototype` as its prototype, which is why `point.toString` works.

```
function fresh() { return { n: 0 }; }
let a = fresh(), b = fresh();
a.n = 1;
console.log(b.n); // 0 — two independent objects

const shared = { n: 0 };
let c = shared, d = shared;
c.n = 1;
console.log(d.n); // 1 — one object, two variables
```

