const thermometer = {
  _celsius: 0,
  set celsius(v) {
    if (typeof v !== "number" || !Number.isFinite(v) || v < -273.15) {
      throw new RangeError(`invalid celsius value: ${v}`);
    }
    this._celsius = v;
  },
  get celsius() { return this._celsius; },
  get fahrenheit() { return this._celsius * 1.8 + 32; }
};
```

