Count the lines of a log file whose chunks arrive as `"INFO a\nINFO b"`, then `"​c\nINFO d\n"` — where the line `"INFO bc"` straddles the boundary. Apply the leftover pattern:
```js
async function countLines(path) {
  let leftover = "";
  let count = 0;
  for await (const chunk of createReadStream(path, "utf8")) {
    const lines = (leftover + chunk).split("\n");
    leftover = lines.pop();     // may be a partial line
    count += lines.length;
  }
  return count + (leftover ? 1 : 0);
}
```

