  let text = strings[0];
  for (let i = 1; i < strings.length; i++) text += '$' + i + strings[i];
  return { text, values };
}
sql`SELECT * FROM users WHERE name = ${name} AND age > ${age}`;
// { text: 'SELECT * FROM users WHERE name = $1 AND age > $2', values: [name, age] }
```
The same shape gives safe URLs (`encodeURIComponent` each value) and safe shell commands — the tag decides the encoding its sink requires.

steps.text:
```js
function escapeHtml(strings, ...values) {
  let s = strings[0];                    // trusted literal text
  for (let i = 1; i < strings.length; i++) {
    const v = String(values[i - 1]);     // untrusted data
    s += v.replace(/&/g, '&amp;')
           .replace(/</g, '&lt;')
           .replace(/>/g, '&gt;')
           .replace(/"/g, '&quot;')
           .replace(/'/g, '&#39;');
    s += strings[i];                      // trusted text again
  }
  return s;
}
```

