```js
function makeLoggingProxy(target, label) {
  return new Proxy(target, {
    get(t, prop, receiver) {
      const value = Reflect.get(t, prop, receiver);
      console.log('get    ' + label + '.' + String(prop) + ' -> ' + value);
      return value;
    },
    set(t, prop, value, receiver) {
      const ok = Reflect.set(t, prop, value, receiver);
      console.log('set    ' + label + '.' + String(prop) + ' = ' + value + ' [' + ok + ']');
      return ok;
    },
    has(t, prop) {
      const found = Reflect.has(t, prop);
      console.log('has    ' + label + '.' + String(prop) + ' [' + found + ']');
      return found;
    },
    deleteProperty(t, prop) {
      const ok = Reflect.deleteProperty(t, prop);
      console.log('delete ' + label + '.' + String(prop) + ' [' + ok + ']');
      return ok;
    }
  });
}
``` Each trap does its work — logging — and then forwards the operation with the matching `Reflect` function, returning what it returns.

```js
function privacyProxy(target) {
  const guard = name =>
    typeof name === 'string' && name.startsWith('_');
  return new Proxy(target, {
    get(t, prop, receiver) {
      if (guard(prop)) throw new TypeError('private property ' + String(prop));
      const value = Reflect.get(t, prop, receiver);
      return typeof value === 'function' ? value.bind(t) : value;
    },
    set(t, prop, value, receiver) {
      if (guard(prop)) throw new TypeError('private property ' + String(prop));
      return Reflect.set(t, prop, value, receiver);
    },
    has(t, prop) {
      if (guard(prop)) return false;
      return Reflect.has(t, prop);
    },
    deleteProperty(t, prop) {
      if (guard(prop)) return false;
      return Reflect.deleteProperty(t, prop);
    }
  });
}
```

```js
class Counter {
  constructor(start = 0) {
    this._value = start;      // private by convention
    this.n = () => this._value;   // public methods close over this
    return privacyProxy(this);
  }
  increment() { this._value++; return this._value; }
}
``` Because constructors may return an object, `new Counter()` hands callers the proxy, while `this` inside the methods remains the raw target.

