Write `greet.js` so that `node greet.js --name Ada --times 3` greets three times, with a default for missing flags and clear errors for malformed ones — reading nothing but `process.argv`.
```js
function parseArgs(argv) {
  const args = { name: "world", times: 1 };
  for (let i = 2; i < argv.length; i++) {
    const arg = argv[i];
    if (!arg.startsWith("--")) {
      throw new Error(`unexpected argument: ${arg}`);
    }
    const key = arg.slice(2);
    const value = argv[i + 1];
    if (value === undefined || value.startsWith("--")) {
      throw new Error(`missing value for ${arg}`);
    }
    args[key] = value;
    i++;                      // consume the value we just used
  }
  return args;
}

const args = parseArgs(process.argv);
for (let i = 0; i < Number(args.times); i++) {
  console.log(`Hello, ${args.name}!`);
}
```

