examples.problem:
Split a computation across two Node processes: the parent forks a child, sends it work as a message, and receives the answer on the built-in IPC channel — the crash-isolated alternative to running the work in-process.
```js
// ---------- parent.js ----------
const { fork } = require("node:child_process");

const child = fork("child.js");
console.log("child pid:", child.pid);

child.send({ type: "sum", numbers: [1, 2, 3, 4, 5] });

child.on("message", (m) => {
  if (m.type === "result") {
    console.log("sum =", m.value);
    child.kill();                     // SIGTERM, then "exit" fires
  }
});
child.on("exit", (code) => console.log("child exited", code));

// ---------- child.js ----------
process.on("message", (m) => {
  if (m.type === "sum") {
    process.send({
      type: "result",
      value: m.numbers.reduce((a, b) => a + b, 0),
    });
  }
});
```

A deliberately expensive `fib(40)` would freeze a single-threaded server for seconds. Move it to a worker thread and prove the main thread stays responsive — then make the shared-counter increment race-free with `Atomics`.
```js
// ---------- main.js ----------
const { Worker } = require("node:worker_threads");

const worker = new Worker("./heavy.js", { workerData: { n: 40 } });

worker.on("message", (result) => {
  clearInterval(heartbeat);
  console.log(`fib(40) = ${result}`);
});
worker.on("error", (err) => { clearInterval(heartbeat); console.error(err); });

// proof of responsiveness: this keeps firing while fib grinds
const heartbeat = setInterval(() => {
  const mb = Math.round(process.memoryUsage().heapUsed / 1e6);
  console.log(`main thread alive (heap ${mb} MB)`);
}, 500);

// ---------- heavy.js ----------
const { parentPort, workerData } = require("node:worker_threads");

function fib(n) { return n < 2 ? n : fib(n - 1) + fib(n - 2); }

parentPort.postMessage(fib(workerData.n));

// ---------- the Atomics one-liner (either file) ----------
const shared = new Int32Array(new SharedArrayBuffer(4));
Atomics.add(shared, 0, 1);   // increment that can never interleave
```

