```js
const todos = document.querySelector("#todos");
todos.addEventListener("click", (event) => {
  const item = event.target.closest("li");
  if (!item) { return; }
  if (event.target.closest("[data-del]")) { item.remove(); return; }
  if (event.target.closest("[data-done]")) { item.classList.toggle("done"); }
});
```
The handler climbs to the owning item once, then routes by which action button matched — working for items added long after binding.

```js
const form = document.querySelector("#addForm");
form.addEventListener("submit", (event) => {
  event.preventDefault();
  const text = form.elements.task.value.trim();
  if (!text) { return; }
  const li = document.createElement("li");
  li.textContent = text;
  const done = document.createElement("button");
  done.textContent = "Done";
  done.setAttribute("data-done", "");
  const del = document.createElement("button");
  del.textContent = "Delete";
  del.setAttribute("data-del", "");
  li.append(" ", done, " ", del);
  todos.append(li);
  form.reset();
});
```
Submit handling captures both button clicks and Enter keys, `preventDefault` stops navigation, and `textContent` keeps task text inert.

```js
const email = document.querySelector("#email");
email.addEventListener("input", () => {
  const ok = email.checkValidity();
  email.classList.toggle("bad", !ok);
  email.setAttribute("aria-invalid", String(!ok));
});
```
Every keystroke rechecks the built-in email rule, syncing visual and ARIA state so guidance arrives while typing, not after.

```js
const pw = document.querySelector("#pw");
const pw2 = document.querySelector("#pw2");
function checkMatch() {
  const mismatch = pw.value !== pw2.value;
  pw2.setCustomValidity(mismatch ? "Passwords must match." : "");
}
pw.addEventListener("input", checkMatch);
pw2.addEventListener("input", checkMatch);
```
Custom validity plugs the confirmation rule into the native validation engine so it participates in submit gating automatically.

```js
const form = document.querySelector("#signup");
form.addEventListener("submit", (event) => {
  if (!form.checkValidity()) {
    event.preventDefault();
    form.reportValidity();
  }
});
```
The submit handler enforces the final checkpoint and surfaces native messages, catching Enter-key submits that button wiring would miss.

```js
async function loadUser(id) {
  let res;
  try {
    res = await fetch("/api/users/" + id);
  } catch (err) {
    throw new Error("Network unreachable", { cause: err });
  }
  if (res.status === 404) {
    throw new RangeError("No user with id " + id);
  }
  if (!res.ok) {
    throw new Error("Server responded " + res.status);
  }
  return res.json();
}
```
Each failure class gets its own error type and message, with the low-level fault preserved under `cause` for inspection.

```js
const box = document.querySelector("#profile");
try {
  const user = await loadUser(7);
  box.textContent = user.name;
} catch (err) {
  console.assert(err instanceof Error, "expected an Error object");
  box.textContent = "Could not load profile: " + err.message;
} finally {
  box.classList.add("settled");
}
```
The UI boundary catches once, asserts the contract, renders a human message, and always marks settled state in `finally`.

```js
function onSave() {
  const form = document.querySelector("#editor");
  const title = form.querySelector("#title");
  console.assert(form, "editor form must exist");
  console.assert(title, "title field must exist");
  title.focus();
}
```
A line breakpoint on the crash plus asserts on each lookup reveal the null binding directly; here a renamed id leaves `form` null, so the property read was doomed before the title line ran.

Start both fetches one after the other so the second waits:
```js
async function loadSequential(ids) {
  const a = await fetchUser(ids[0]);
  const b = await fetchUser(ids[1]);
  return [a, b];
}
```

Create both promises before awaiting anything, then join once:
```js
async function loadParallel(ids) {
  const p1 = fetchUser(ids[0]);
  const p2 = fetchUser(ids[1]);
  return await Promise.all([p1, p2]);
}
```

Time both variants over the same fake latency:
```js
console.time("seq");
await loadSequential([1, 2]);
console.timeEnd("seq");
console.time("par");
await loadParallel([1, 2]);
console.timeEnd("par");
```

Keep one try block around the dependent steps:
```js
async function loadDashboard(userId) {
  try {
    const user = await fetchUser(userId);
    const orders = await fetchOrders(user.id);
    return { user, orders };
  } catch (err) {
    throw new Error("Dashboard failed to load: " + err.message);
  } finally {
    hideSpinner();
  }
}
```

