steps.text:
Wrap every value so expiry travels with it:
```js
function savePref(key, value, maxAgeMs) {
  const record = { value: value, expires: Date.now() + maxAgeMs };
  try {
    localStorage.setItem(key, JSON.stringify(record));
  } catch (err) {
    console.warn("Storage unavailable, keeping in memory");
    memoryCache[key] = record;
  }
}
```

Treat expired or corrupt records as missing:
```js
function readPref(key, fallback) {
  try {
    const raw = localStorage.getItem(key);
    if (!raw) return fallback;
    const rec = JSON.parse(raw);
    if (rec.expires < Date.now()) {
      localStorage.removeItem(key);
      return fallback;
    }
    return rec.value;
  } catch (err) {
    return fallback;
  }
}
```

Version once and create the outbox store:
```js
const openReq = indexedDB.open("appdb", 1);
openReq.onupgradeneeded = function () {
  openReq.result.createObjectStore("outbox", { keyPath: "id", autoIncrement: true });
};
```

Write each submission as a record in a transaction:
```js
function enqueue(payload) {
  const db = openReq.result;
  const tx = db.transaction("outbox", "readwrite");
  tx.objectStore("outbox").add({ payload: payload, savedAt: Date.now() });
}
```

Read all queued records and POST them in order:
```js
window.addEventListener("online", flushOutbox);
async function flushOutbox() {
  const rows = await readAll("outbox");
  for (const row of rows) { await postPayload(row.payload); }
  await clearStore("outbox");
}
```

Keep the worker free of DOM calls:
```js
self.onmessage = function (e) {
  const arr = e.data.values;
  arr.sort(function (a, b) { return a - b; });
  self.postMessage({ type: "done", values: arr });
};
```

Send the batch and listen for the answer:
```js
const sorter = new Worker("sorter.js");
sorter.onmessage = function (e) {
  if (e.data.type === "done") renderRows(e.data.values);
};
sorter.onerror = function (err) { showNotice("Sort failed"); };
sorter.postMessage({ values: bigArray });
```

Release the thread when the job completes:
```js
sorter.onmessage = function (e) {
  renderRows(e.data.values);
  sorter.terminate();
};
```

Allocate the pixel bytes once:
```js
const buffer = new ArrayBuffer(16 * 1024 * 1024);
const pixels = new Uint8ClampedArray(buffer);
fillPixels(pixels);
```

Never touch the sent buffer again on this side:
```js
console.log(buffer.byteLength);
filterWorker.onmessage = function (e) {
  paintImage(e.data.pixels);
};
```

The worker transfers the filtered bytes back the same way:
```js
self.onmessage = function (e) {
  const out = applyFilter(e.data.pixels);
  self.postMessage({ pixels: out }, [out]);
};
```

Name what the module provides:
```js
let items = [];
export function addItem(item) { items.push(item); }
export function total() {
  return items.reduce(function (s, i) { return s + i.price; }, 0);
}
```

Declare the dependency at the top of the consumer:
```js
import { addItem, total } from "./cart.js";
addItem({ name: "Book", price: 19 });
console.log(total());
```

Mark the entry script so imports resolve:
```js
// in index.html
// <script type="module" src="/src/main.js"></script>
import { total } from "./cart.js";
```

Defer the heavy screen with a dynamic import:
```js
import { lazy, Suspense } from "react";
const Admin = lazy(function () { return import("./Admin.jsx"); });
function App() {
  return <Suspense fallback={<p>Loading</p>}><Admin /></Suspense>;
}
```

Restrict status to its vocabulary and mark the subtitle optional:
```ts
interface Article {
  id: string;
  title: string;
  subtitle?: string;
  status: "draft" | "review" | "published";
  readonly slug: string;
}
```

Build an object the checker accepts:
```ts
const post: Article = {
  id: "a1",
  title: "Async Basics",
  status: "draft",
  slug: "async-basics"
};
```

Say what goes in and what comes out:
```ts
type Line = { price: number; qty: number };
export function lineTotal(lines: Line[]): number {
  let sum = 0;
  for (const line of lines) { sum += line.price * line.qty; }
  return sum;
}
```

Demand the minimum shape the UI needs:
```ts
interface HasId { id: string }
async function getJSON<T extends HasId>(url: string): Promise<T> {
  const res = await fetch(url);
  if (!res.ok) throw new Error("Fetch failed: " + res.status);
  return (await res.json()) as T;
}
```

The caller fixes T to its own type:
```ts
interface User extends HasId { name: string }
const user = await getJSON<User>("https://api.example.com/users/7");
console.log(user.name);
```

A type without id fails before running:
```ts
interface NoId { name: string }
// getJSON<NoId>("https://api.example.com/x");
```
The compiler reports that NoId does not satisfy the extends clause.

Define the full shape once:
```ts
interface User { id: string; name: string; email: string; role: string }
type UserUpdate = Partial<User>;
type UserCard = Pick<User, "id" | "name">;
```

An update needs only the changed fields:
```ts
function applyUpdate(id: string, patch: UserUpdate): void {
  savePatch(id, patch);
}
applyUpdate("u7", { name: "Ada" });
```

Cards cannot see emails by construction:
```ts
function renderCard(card: UserCard): void {
  paintRow(card.id, card.name);
}
```

Tag each case with a literal status:
```ts
type ProfileState =
  | { status: "loading" }
  | { status: "ready"; name: string; bio: string }
  | { status: "failed"; message: string };
```

Switch on the discriminant and let each branch narrow:
```ts
function render(state: ProfileState): string {
  switch (state.status) {
    case "loading": return "Spinner";
    case "ready": return state.name + " " + state.bio;
    case "failed": return "Retry: " + state.message;
  }
}
```

Give each role its own shape:
```ts
interface Admin { kind: "admin"; scope: string }
interface Member { kind: "member"; team: string }
type Actor = Admin | Member;
```

Teach the checker the distinction:
```ts
function isAdmin(a: Actor): a is Admin {
  return a.kind === "admin";
}
```

Narrow first, then use role fields:
```ts
function grant(a: Actor): string {
  if (isAdmin(a)) return "all:" + a.scope;
  return "team:" + a.team;
}
```

