steps.text:
Set the safety and output baseline:
```ts
// tsconfig.json
{
  "compilerOptions": {
    "target": "ES2022",
    "module": "ESNext",
    "moduleResolution": "Bundler",
    "strict": true,
    "skipLibCheck": true
  }
}
```

Shorten cross-cutting imports consistently:
```ts
// tsconfig.json paths
{
  "compilerOptions": {
    "baseUrl": ".",
    "paths": { "@shared/*": ["src/shared/*"] }
  }
}
```

Register the same alias where code actually runs:
```ts
// vite.config.ts
import { defineConfig } from "vite";
export default defineConfig({
  resolve: { alias: { "@shared": "/src/shared" } }
});
```

The compiler reports the value as possibly null at the render line:
```ts
function hello(name: string | null): string {
  return "Hi " + name;
}
```

Handle the absent case explicitly:
```ts
function hello(name: string | null): string {
  if (name === null) return "Hi guest";
  return "Hi " + name;
}
```

Name the callback payload explicitly:
```tsx
interface SearchProps {
  initial: string;
  onSearch: (query: string) => void;
}
```

Bind the event generic to the input element:
```tsx
import { useState } from "react";
import type { ChangeEvent } from "react";
function SearchBox(props: SearchProps) {
  const [query, setQuery] = useState(props.initial);
  function onChange(e: ChangeEvent<HTMLInputElement>): void {
    setQuery(e.target.value);
  }
  return <input value={query} onChange={onChange} />;
}
```

Keep the contract in shared code:
```ts
interface CreatePost { title: string; body: string }
interface Post extends CreatePost { id: string }
```

The client sends exactly the contract:
```ts
async function createPost(input: CreatePost): Promise<Post> {
  const res = await fetch("/api/posts", {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify(input)
  });
  if (!res.ok) throw new Error("Create failed");
  return (await res.json()) as Post;
}
```

The server parses unknown input into the same shape:
```ts
async function handleCreate(raw: unknown): Promise<Post> {
  const input = parseCreatePost(raw);
  return savePost(input);
}
```

Type the title and the nested content slot:
```tsx
interface CardProps {
  title: string;
  children: import("react").ReactNode;
}
```

Return a single section using expressions only:
```tsx
function Card(props: CardProps) {
  return (
    <section className="card">
      <h2>{props.title}</h2>
      <div>{props.children}</div>
    </section>
  );
}
```

Nest any body without changing the card:
```tsx
function Page() {
  return (
    <Card title="Profile">
      <p>Ada builds interfaces.</p>
    </Card>
  );
}
```

Keep the count where it is shared:
```tsx
import { useState } from "react";
function Cart() {
  const [count, setCount] = useState(1);
  return <Stepper value={count} onChange={setCount} />;
}
```

The child calls back instead of mutating:
```tsx
interface StepperProps { value: number; onChange: (n: number) => void }
function Stepper(props: StepperProps) {
  return <button onClick={function () { props.onChange(props.value + 1); }}>More</button>;
}
```

Store the tick in component memory:
```tsx
import { useEffect, useState } from "react";
function Clock() {
  const [now, setNow] = useState(function () { return new Date(); });
  return <p>{now.toLocaleTimeString()}</p>;
}
```

Create and clear the timer in one effect:
```tsx
useEffect(function () {
  const id = setInterval(function () { setNow(new Date()); }, 1000);
  return function () { clearInterval(id); };
}, []);
```

Rerun whenever the reactive id changes:
```tsx
import { useEffect, useState } from "react";
function Profile(props: { id: string }) {
  const [name, setName] = useState("");
  useEffect(function () {
    const ctrl = new AbortController();
    fetch("/api/users/" + props.id, { signal: ctrl.signal })
      .then(function (r) { return r.json(); })
      .then(function (u) { setName(u.name); })
      .catch(function () {});
    return function () { ctrl.abort(); };
  }, [props.id]);
  return <p>{name}</p>;
}
```

Give the reconciler stable identity:
```tsx
function TodoList(props: { items: { id: string; text: string }[] }) {
  return (
    <ul>
      {props.items.map(function (item) {
        return <TodoRow key={item.id} item={item} />;
      })}
    </ul>
  );
}
```

Each row owns its edit buffer safely:
```tsx
import { useState } from "react";
function TodoRow(props: { item: { id: string; text: string } }) {
  const [draft, setDraft] = useState(props.item.text);
  return <input value={draft} onChange={function (e) { setDraft(e.target.value); }} />;
}
```

Swapping to key by position detaches drafts on sort:
```tsx
// {props.items.map(function (item, i) { return <TodoRow key={i} item={item} />; })}
```
Sorting then leaves text in the old positions while ids move, proving keys carry identity.

Track what was visited to time feedback:
```tsx
import { useState } from "react";
function Signup() {
  const [email, setEmail] = useState("");
  const [touched, setTouched] = useState(false);
  const error = touched && !email.includes("@") ? "Enter a valid email" : "";
  return <form>{error}</form>;
}
```

Bind value and change for live checks:
```tsx
<input
  value={email}
  onChange={function (e) { setEmail(e.target.value); }}
  onBlur={function () { setTouched(true); }}
/>
```

Stop reloads and block bad posts:
```tsx
function onSubmit(e: import("react").FormEvent): void {
  e.preventDefault();
  if (!email.includes("@")) { setTouched(true); return; }
  createAccount(email);
}
```

Publish the value once near the root:
```tsx
import { createContext, useMemo, useState } from "react";
const ThemeCtx = createContext({ theme: "light", toggle: function () {} });
function ThemeProvider(props: { children: import("react").ReactNode }) {
  const [theme, setTheme] = useState("light");
  const value = useMemo(function () {
    return { theme: theme, toggle: function () { setTheme(function (t) { return t === "light" ? "dark" : "light"; }); } };
  }, [theme]);
  return <ThemeCtx.Provider value={value}>{props.children}</ThemeCtx.Provider>;
}
```

Read without intermediate props:
```tsx
import { useContext } from "react";
function Toggle() {
  const ctx = useContext(ThemeCtx);
  return <button onClick={ctx.toggle}>{ctx.theme}</button>;
}
```

Hide the storage ceremony in one hook:
```tsx
import { useEffect, useState } from "react";
function useLocalStorage(key: string, initial: string): [string, (v: string) => void] {
  const [value, setValue] = useState(function () {
    try { return localStorage.getItem(key) || initial; } catch (err) { return initial; }
  });
  useEffect(function () {
    try { localStorage.setItem(key, value); } catch (err) {}
  }, [key, value]);
  return [value, setValue];
}
```

Each caller owns independent state with shared logic:
```tsx
function ThemePicker() {
  const [theme, setTheme] = useLocalStorage("theme", "light");
  return <button onClick={function () { setTheme(theme === "light" ? "dark" : "light"); }}>{theme}</button>;
}
```

Name each case in order:
```tsx
function Inbox(props: { status: string; items: string[] }) {
  if (props.status === "failed") return <p>Failed to load. Retry.</p>;
  if (props.status === "loading") return <p>Loading messages</p>;
  if (props.items.length === 0) return <p>No messages yet.</p>;
  return <ul>{props.items.map(function (m) { return <li key={m}>{m}</li>; })}</ul>;
}
```

Own status above both the filter and the list:
```tsx
import { useState } from "react";
function InboxPage() {
  const [query, setQuery] = useState("");
  return <Inbox status="ready" items={["hello"]} />;
}
```

Render only from props with no fetching:
```tsx
interface Row { id: string; name: string }
function UserTable(props: { rows: Row[]; onPick: (id: string) => void }) {
  return (
    <table>
      <tbody>
        {props.rows.map(function (r) {
          return <tr key={r.id} onClick={function () { props.onPick(r.id); }}><td>{r.name}</td></tr>;
        })}
      </tbody>
    </table>
  );
}
```

Map server data to view props at the edge:
```tsx
function TeamPage() {
