     PreparedStatement stat = conn.prepareStatement(insert, Statement.RETURN_GENERATED_KEYS)) {
    // generated-keys-pattern: ask for keys at prepare time, read after update
    stat.setString(1, "Le Guin");
    stat.setString(2, "A Wizard of Earthsea");
    stat.executeUpdate();
    try (ResultSet keys = stat.getGeneratedKeys()) {
